exports.cancelImmediately = ({ subscriptionId }) => {
  const result = unsubscribe({ subscriptionId });
  if (!result.ok) return result;
  const sub = findSubscription(subscriptionId);
  const user = sub ? findById(sub.userId) : null;
  record({ userId: sub && sub.userId, kind: 'subscription_cancelled', props: { subscriptionId } });
  if (user) sendEmail({ to: user.email, key: 'subscription_cancelled', vars: { subscriptionId } });
